FUNCTION_BLOCK FB_Temperatura
VAR_INPUT
    rawTemp : INT; // Entrada de temperatura cruda (0 a 27648)
END_VAR

VAR_OUTPUT
    tempC : REAL; // Temperatura en grados Celsius (0.0 a 100.0)
    enfriador : BOOL; // Estado del enfriador (TRUE: activado, FALSE: desactivado)
    almSensor : BOOL; // Estado de la alarma del sensor (TRUE: activada, FALSE: desactivada)
END_VAR

VAR
    tempCPrev : REAL; // Temperatura anterior para la histéresis
    enfriadorPrev : BOOL; // Estado anterior del enfriador para la histéresis
END_VAR

// Calcula la temperatura en grados Celsius
IF rawTemp < 0 OR rawTemp > 27648 THEN
    tempC := 0.0;
    almSensor := TRUE;
    enfriador := FALSE;
ELSE
    tempC := rawTemp / 276.48; // Conversión de 0-27648 a 0.0-100.0 grados Celsius
    almSensor := FALSE;

    // Control del enfriador con histéresis
    IF tempC >= 80.0 THEN
        enfriador := TRUE;
    ELSIF tempC <= 75.0 THEN
        enfriador := FALSE;
    ELSE
        enfriador := enfriadorPrev; // Mantener el estado anterior si está en la zona de histéresis
    END_IF
END_IF

// Actualiza el estado anterior del enfriador
enfriadorPrev := enfriador;

FUNCTION_BLOCK FB_Temperatura
VAR_INPUT
    rawTemp : INT; // Señal analógica cruda (0 a 27648)
END_VAR

VAR_OUTPUT
    tempC : REAL; // Temperatura escalada en grados Celsius (0.0 a 100.0)
    enfriador : BOOL; // Estado del enfriador
    almSensor : BOOL; // Alarma de sensor fuera de rango
END_VAR

// 1. Evaluación de alarma por fuera de rango
IF rawTemp < 0 OR rawTemp > 27648 THEN
    almSensor := TRUE;
ELSE
    almSensor := FALSE;
END_IF;

// 2. Acondicionamiento y escalado de la señal a REAL (0.0 - 100.0)
tempC := (INT_TO_REAL(rawTemp) / 27648.0) * 100.0;

// 3. Control del enfriador con histéresis y enclavamiento por alarma
IF almSensor THEN
    // Por seguridad, si el sensor falla, se desactiva el enfriador
    enfriador := FALSE;
ELSE
    // Lógica de histéresis
    IF tempC >= 80.0 THEN
        enfriador := TRUE;
    ELSIF tempC <= 75.0 THEN
        enfriador := FALSE;
    END_IF;
    // Si tempC está entre 75.0 y 80.0, 'enfriador' conserva su estado anterior
END_IF;

END_FUNCTION_BLOCK

FUNCTION_BLOCK FB_Temperatura
VAR_INPUT
    rawTemp : INT;  // Entrada de temperatura cruda (0-27648)
END_VAR

VAR_OUTPUT
    tempC : REAL;   // Temperatura en grados Celsius (0.0-100.0)
    enfriador : BOOL;  // Estado del enfriador (TRUE/FALSE)
    almSensor : BOOL;  // Alarma del sensor (TRUE/FALSE)
END_VAR

VAR
    tempCPrev : REAL;  // Valor previo de temperatura en Celsius
    enfriadorPrev : BOOL;  // Estado previo del enfriador
END_VAR

// Calculo de la temperatura en Celsius
IF rawTemp >= 0 AND rawTemp <= 27648 THEN
    tempC := rawTemp * 100.0 / 27648.0;
    almSensor := FALSE;
ELSE
    tempC := 0.0;
    almSensor := TRUE;
END_IF;

// Control del enfriador con histéresis
IF tempC >= 80.0 THEN
    enfriador := TRUE;
ELSIF tempC <= 75.0 THEN
    enfriador := FALSE;
ELSE
    enfriador := enfriadorPrev;  // Mantener el estado anterior si está en el rango de histéresis
END_IF;

// Actualizar el estado previo del enfriador
enfriadorPrev := enfriador;

END_FUNCTION_BLOCK

FUNCTION_BLOCK FB_Temperatura
VAR_INPUT
    rawTemp : INT; // Señal analógica cruda del sensor (0 a 27648)
END_VAR

VAR_OUTPUT
    tempC : REAL; // Temperatura escalada en grados Celsius (0.0 a 100.0)
    enfriador : BOOL; // Comando de activación del enfriador
    almSensor : BOOL; // Alarma de sensor fuera de rango
END_VAR

// 1. Acondicionamiento y escalado de la señal
// Se convierte el valor entero a real y se escala al rango 0.0 - 100.0
tempC := (INT_TO_REAL(rawTemp) / 27648.0) * 100.0;

// 2. Detección de fallas del sensor (fuera de rango)
IF rawTemp < 0 OR rawTemp > 27648 THEN
    almSensor := TRUE;
ELSE
    almSensor := FALSE;
END_IF;

// 3. Control del enfriador con histéresis y seguridad
IF almSensor THEN
    // Por seguridad, si el sensor falla, se desactiva el enfriador
    enfriador := FALSE;
ELSIF tempC >= 80.0 THEN
    // Activar enfriador si alcanza o supera el umbral superior
    enfriador := TRUE;
ELSIF tempC <= 75.0 THEN
    // Desactivar enfriador si desciende al umbral inferior o menos
    enfriador := FALSE;
END_IF;
// Nota: Si tempC está entre 75.0 y 80.0, no se ejecuta ninguna condición, 
// por lo que 'enfriador' conserva su estado anterior (histéresis).

END_FUNCTION_BLOCK

